package com.fidecode.biteflow.application.integration;import com.fidecode.biteflow.application.integration.dto.*;import com.fidecode.biteflow.domain.integration.entity.IntegrationConfig;import com.fidecode.biteflow.domain.integration.repository.IntegrationConfigRepository;import jakarta.enterprise.context.ApplicationScoped;import jakarta.inject.Inject;import java.util.UUID;
@ApplicationScoped public class ConfigureIfoodUseCase {private final IntegrationConfigRepository repo;@Inject public ConfigureIfoodUseCase(IntegrationConfigRepository repo){this.repo=repo;}public IntegrationResponse execute(UUID storeId,IfoodIntegrationRequest request){var c=repo.findByStoreIdAndProvider(storeId,"IFOOD").orElse(new IntegrationConfig(storeId,"IFOOD"));c.configureIfood(request.clientId(),request.clientSecret(),request.merchantId());return IntegrationDtoMapper.toResponse(repo.save(c));}}
